<script setup lang="ts">
import { api, friendlyError } from '@lostsky/api/client'
import { useMutation, useQuery } from '@tanstack/vue-query'
import LsButton from '@lostsky/ui/components/LsButton.vue'
import { ArrowLeft, BookOpen, Upload } from '@lucide/vue'
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
interface Field{id:number;name:string;field_key?:string;value_type?:string;input_type?:string;options?:unknown;is_required?:0|1;is_editable?:0|1}
type Value=string|number|boolean|string[]|null
const route=useRoute();const memberId=computed(()=>Number(route.query.id));const values=reactive<Record<number,Value>>({});const uploading=ref<number|null>(null)
const member=useQuery({queryKey:computed(()=>['member',memberId.value]),queryFn:()=>api.get<Record<string,unknown>>('/member/get',{member_id:memberId.value}),enabled:computed(()=>memberId.value>0)});const fields=useQuery({queryKey:['member-fields'],queryFn:()=>api.get<Field[]>('/memberField/index')});const stored=useQuery({queryKey:computed(()=>['member-field-values',memberId.value]),queryFn:()=>api.get<Record<string,unknown>[]>('/memberField/values',{member_id:memberId.value}),enabled:computed(()=>memberId.value>0)});watch(()=>stored.data.value,(list)=>{for(const item of list??[]){const id=Number(item.field_id);values[id]=(item.value_string??item.value_text??item.value_int??item.value_decimal??item.value_datetime??item.value_json??'') as Value}},{immediate:true});const save=useMutation({mutationFn:()=>api.post('/memberField/saveValues',{member_id:memberId.value,values:{...values}})})
const profile=computed(()=>member.data.value?.profile as Record<string,unknown>|undefined);function options(field:Field){let source=field.options;if(typeof source==='string'){try{source=JSON.parse(source)}catch{source=(source as string).split(',')}}return Array.isArray(source)?source.map(item=>typeof item==='object'&&item?{label:String((item as Record<string,unknown>).label??(item as Record<string,unknown>).name??(item as Record<string,unknown>).value),value:String((item as Record<string,unknown>).value??(item as Record<string,unknown>).label??(item as Record<string,unknown>).name)}:{label:String(item),value:String(item)}):[]}function toggle(field:Field,value:string,on:boolean){const current=Array.isArray(values[field.id])?values[field.id] as string[]:[];values[field.id]=on?[...new Set([...current,value])]:current.filter(item=>item!==value)}async function upload(field:Field,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=field.id;try{const result=await api.upload<Record<string,unknown>>(file);values[field.id]=String(result.url??result.path??result.id??'')}finally{uploading.value=null}}
</script>
<template><div class="member-detail"><header><RouterLink to="/members"><ArrowLeft :size="18"/>返回成员列表</RouterLink><RouterLink :to="`/docs?target_type=teamMember&target_id=${memberId}`"><BookOpen :size="18"/>成员文档</RouterLink></header><p v-if="member.isError.value" class="error" role="alert">{{friendlyError(member.error.value)}}</p><section v-else-if="member.data.value" class="identity"><div class="avatar"><img v-if="profile?.avatar||member.data.value.avatar" :src="String(profile?.avatar||member.data.value.avatar)" alt="成员头像"><span v-else>{{String(profile?.nickname||member.data.value.nickname||'成').slice(0,1)}}</span></div><div><small>USER #{{member.data.value.user_id}}</small><h2>{{profile?.nickname||member.data.value.nickname||`成员 #${memberId}`}}</h2><p>{{profile?.description||member.data.value.description||'暂无成员简介'}}</p></div><strong>{{Number(member.data.value.is_blocked)?'已封禁':'正常'}}</strong></section><form class="fields" @submit.prevent="save.mutate()"><div class="section-title"><div><h3>自定义资料</h3><p>团队定义的业务字段会显示在这里。</p></div><LsButton type="submit" :loading="save.isPending.value">保存资料</LsButton></div><p v-if="fields.isPending.value">正在读取字段…</p><div v-else-if="!fields.data.value?.length" class="empty">团队尚未配置成员字段。</div><div v-else class="field-grid"><label v-for="field in fields.data.value" :key="field.id"><span>{{field.name}} <b v-if="field.is_required">*</b><small>{{field.field_key}}</small></span><textarea v-if="field.input_type==='textarea'" v-model="values[field.id] as string" rows="4" :disabled="field.is_editable===0"></textarea><select v-else-if="field.input_type==='select'" v-model="values[field.id] as string" :disabled="field.is_editable===0"><option value="">请选择</option><option v-for="item in options(field)" :key="item.value" :value="item.value">{{item.label}}</option></select><div v-else-if="field.input_type==='radio'" class="choices"><label v-for="item in options(field)" :key="item.value"><input v-model="values[field.id]" type="radio" :name="`field-${field.id}`" :value="item.value" :disabled="field.is_editable===0">{{item.label}}</label></div><div v-else-if="field.input_type==='checkbox'&&field.value_type!=='bool'" class="choices"><label v-for="item in options(field)" :key="item.value"><input type="checkbox" :checked="Array.isArray(values[field.id])&&(values[field.id] as string[]).includes(item.value)" :disabled="field.is_editable===0" @change="toggle(field,item.value,($event.target as HTMLInputElement).checked)">{{item.label}}</label></div><label v-else-if="field.value_type==='bool'" class="bool"><input v-model="values[field.id]" type="checkbox" :disabled="field.is_editable===0">是</label><div v-else-if="field.input_type==='upload'" class="upload"><input v-model="values[field.id] as string" :disabled="field.is_editable===0"><label><Upload :size="16"/>{{uploading===field.id?'上传中':'上传'}}<input type="file" :disabled="field.is_editable===0" @change="upload(field,$event)"></label></div><input v-else v-model="values[field.id] as string" :type="field.input_type==='date'?'date':field.input_type==='datetime'?'datetime-local':['int','decimal'].includes(field.value_type??'')?'number':'text'" :disabled="field.is_editable===0"></label></div><p v-if="save.isError.value" class="error" role="alert">{{friendlyError(save.error.value)}}</p><p v-if="save.isSuccess.value" class="success" role="status">成员资料已保存。</p></form></div></template>
<style scoped>.member-detail{display:grid;gap:1rem}.member-detail>header{display:flex;justify-content:space-between;gap:1rem}.member-detail>header a{min-height:44px;display:flex;align-items:center;gap:.4rem;color:var(--sky-lost-strong)}.identity{display:grid;grid-template-columns:64px minmax(0,1fr);gap:1rem;padding:1.25rem;color:white;background:var(--sky-night);border-radius:10px}.avatar{width:64px;height:64px;display:grid;place-items:center;overflow:hidden;background:var(--sky-lost-strong);border-radius:10px;font-size:1.4rem;font-weight:700}.avatar img{width:100%;height:100%;object-fit:cover}.identity small{color:var(--sky-lost)}.identity h2,.identity p{margin:0}.identity p{margin-top:.35rem;color:oklch(.74 .012 210)}.identity>strong{grid-column:1/3;width:fit-content;padding:.3rem .55rem;color:var(--sky-night);background:var(--afterglow);border-radius:6px;font-size:.78rem}.fields{display:grid;gap:1rem;padding:1rem;background:white;border:1px solid var(--line);border-radius:10px}.section-title{display:flex;align-items:center;justify-content:space-between;gap:1rem}.section-title h3,.section-title p{margin:0}.section-title p{color:var(--muted-ink);font-size:.8rem}.field-grid{display:grid;gap:1rem}.field-grid>label{display:grid;gap:.4rem;font-size:.84rem;font-weight:650}.field-grid>label>span small{display:block;color:var(--muted-ink);font-weight:400}.field-grid b{color:var(--danger)}.field-grid input:not([type=checkbox]):not([type=radio]):not([type=file]),.field-grid textarea,.field-grid select{width:100%;min-height:44px;padding:.6rem .7rem;border:1px solid var(--line);border-radius:8px}.choices{display:flex;flex-wrap:wrap;gap:.4rem}.choices label,.bool{min-height:42px;display:flex!important;align-items:center;gap:.4rem;padding:0 .6rem;background:var(--cloud);border-radius:7px}.upload{display:grid;grid-template-columns:1fr auto}.upload>label{display:flex;align-items:center;gap:.35rem;padding:0 .8rem;color:white;background:var(--sky-lost-strong);border-radius:0 8px 8px 0}.upload input[type=file]{display:none}.error,.success,.empty{padding:1rem;border:1px solid var(--line);border-radius:8px}.error{color:var(--danger)}.success{color:var(--success)}.empty{text-align:center;color:var(--muted-ink)}@media(min-width:720px){.identity{grid-template-columns:72px minmax(0,1fr) auto;align-items:center}.identity>strong{grid-column:auto}}</style>
